-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.releases (
  id integer not null,
  status text not null,
  title text not null,
  schema_version integer not null,
  fingerprint text not null,
  before_fingerprint text not null,
  public_fingerprint text,
  shape text not null,
  checks jsonb not null,
  changes jsonb default '{}'::jsonb not null,
  published_by text not null,
  published_at timestamp with time zone default now() not null,
  reverted_by text,
  reverted_at timestamp with time zone,
  before_digests jsonb,
  public_digests jsonb,
  constraint releases_pkey PRIMARY KEY (id),
  constraint releases_check CHECK (((status = 'reverted'::text) = (reverted_at IS NOT NULL))),
  constraint releases_checks_check CHECK ((jsonb_typeof(checks) = 'object'::text)),
  constraint releases_id_check CHECK ((id >= 1)),
  constraint releases_published_by_check CHECK (((length(btrim(published_by)) >= 1) AND (length(btrim(published_by)) <= 320))),
  constraint releases_status_check CHECK ((status = ANY (ARRAY['published'::text, 'reverted'::text]))),
  constraint releases_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 300)))
);

alter table public.releases enable row level security;
